def solve(grid):
    n_cols = len(grid[0])
    block_size = n_cols
    num_blocks = len(grid) // block_size

    blocks = []
    for b in range(num_blocks):
        block = [grid[b * block_size + i][:] for i in range(block_size)]
        blocks.append(block)

    for block in blocks:
        is_symmetric = True
        for i in range(block_size):
            for j in range(block_size):
                if block[i][j] != block[j][i]:
                    is_symmetric = False
                    break
            if not is_symmetric:
                break
        if not is_symmetric:
            return block

    return blocks[0]
